<?php
namespace Tests\Feature;
use App\Models\FuelRequest; use App\Models\FuelType; use App\Models\Person; use App\Models\User; use App\Models\Vehicle; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class AuthorizationThreeCopyDocumentTest extends TestCase { use RefreshDatabase;
 public function test_authenticated_user_prints_three_authorization_copies(): void { $actor=User::create(['name'=>'Supervisor','username'=>'auth-doc'.uniqid(),'password'=>'SenhaLocal!12345','auth_source'=>'local','role'=>'supervisor','is_active'=>true]); $fuel=FuelType::create(['name'=>'Gasolina','abbreviation'=>'GAS','active'=>true]); $vehicle=Vehicle::create(['plate'=>'ABC1D23','model'=>'Teste','fuel_type_id'=>$fuel->id,'current_odometer'=>1000,'status'=>'active','maintenance_interval_km'=>10000,'maintenance_interval_days'=>180]); $driver=Person::create(['full_name'=>'Motorista','role'=>'driver','active'=>true]); $request=FuelRequest::create(['request_number'=>321,'requested_at'=>now(),'vehicle_id'=>$vehicle->id,'driver_person_id'=>$driver->id,'fuel_type_id'=>$fuel->id,'odometer'=>1000,'status'=>'approved','approved_by_user_id'=>$actor->id,'approved_at'=>now(),'authorization_at'=>now(),'authorization_expires_at'=>now()->addDays(3),'created_by_user_id'=>$actor->id]); $this->actingAs($actor,'ldap')->get("/requisicoes/{$request->id}/autorizacao-3-vias")->assertOk()->assertSee('VIA POSTO')->assertSee('VIA MOTORISTA')->assertSee('VIA CMRP')->assertSee('VÁLIDO POR 3 DIAS')->assertSee('Responsável administrativo'); }
}
